REFERENCED_BY_SQL = """
SELECT CASE
    WHEN EXISTS (SELECT 1 FROM admission_applications WHERE student_code = %(code)s) THEN 'admission_applications'
    WHEN EXISTS (SELECT 1 FROM admission_enrollment_events WHERE student_code = %(code)s) THEN 'admission_enrollment_events'
    WHEN EXISTS (SELECT 1 FROM assignment_submissions WHERE student_code = %(code)s) THEN 'assignment_submissions'
    WHEN EXISTS (SELECT 1 FROM certificate_requests WHERE student_code = %(code)s) THEN 'certificate_requests'
    WHEN EXISTS (SELECT 1 FROM college_invoices WHERE student_code = %(code)s) THEN 'college_invoices'
    WHEN EXISTS (SELECT 1 FROM consents WHERE student_code = %(code)s) THEN 'consents'
    WHEN EXISTS (SELECT 1 FROM documents WHERE student_code = %(code)s) THEN 'documents'
    WHEN EXISTS (SELECT 1 FROM exam_results WHERE student_code = %(code)s) THEN 'exam_results'
    WHEN EXISTS (SELECT 1 FROM hostel_allocations WHERE student_code = %(code)s) THEN 'hostel_allocations'
    WHEN EXISTS (SELECT 1 FROM hostel_permissions WHERE student_code = %(code)s) THEN 'hostel_permissions'
    WHEN EXISTS (SELECT 1 FROM library_loans WHERE student_code = %(code)s) THEN 'library_loans'
    WHEN EXISTS (SELECT 1 FROM passenger_seats WHERE student_code = %(code)s) THEN 'passenger_seats'
    WHEN EXISTS (SELECT 1 FROM payment_gateway_orders WHERE student_code = %(code)s) THEN 'payment_gateway_orders'
    WHEN EXISTS (SELECT 1 FROM payments WHERE student_code = %(code)s) THEN 'payments'
    WHEN EXISTS (SELECT 1 FROM placement_applications WHERE student_code = %(code)s) THEN 'placement_applications'
    WHEN EXISTS (SELECT 1 FROM student_admission_profiles WHERE student_code = %(code)s) THEN 'student_admission_profiles'
    WHEN EXISTS (SELECT 1 FROM student_attendance WHERE student_code = %(code)s) THEN 'student_attendance'
    WHEN EXISTS (SELECT 1 FROM student_document_links WHERE student_code = %(code)s) THEN 'student_document_links'
    WHEN EXISTS (SELECT 1 FROM student_enrollments WHERE student_code = %(code)s) THEN 'student_enrollments'
    WHEN EXISTS (SELECT 1 FROM student_fee_charges WHERE student_code = %(code)s) THEN 'student_fee_charges'
    WHEN EXISTS (SELECT 1 FROM student_leave_requests WHERE student_code = %(code)s) THEN 'student_leave_requests'
    WHEN EXISTS (SELECT 1 FROM student_parents WHERE student_code = %(code)s) THEN 'student_parents'
    WHEN EXISTS (SELECT 1 FROM student_scholarships WHERE student_code = %(code)s) THEN 'student_scholarships'
    WHEN EXISTS (SELECT 1 FROM student_status_history WHERE student_code = %(code)s) THEN 'student_status_history'
    WHEN EXISTS (SELECT 1 FROM transport_allocations WHERE student_code = %(code)s) THEN 'transport_allocations'
    WHEN EXISTS (SELECT 1 FROM transport_attendance WHERE student_code = %(code)s) THEN 'transport_attendance'
    WHEN EXISTS (SELECT 1 FROM users WHERE student_code = %(code)s) THEN 'users'
END AS referenced_by
"""
# --- end of generated SQL


def query_list(data):
    return sql.fetch_all(data, TABLE, LIST_SQL)


def query_get(data, code):
    record = sql.fetch_one(data, TABLE, GET_SQL, code)
    if record is None:
        raise HTTPException(404, "Record not found")
    return record


def query_save(data, record):
    return sql.save(data, TABLE, record, INSERT_SQL, UPDATE_SQL)


def query_delete(data, code):
    sql.delete(data, TABLE, DELETE_SQL, code)


def query_referenced_by(data, code):
    return sql.referenced_by(data, TABLE, REFERENCED_BY_SQL, code)


class Queries:
    table = TABLE
    list = staticmethod(query_list)
    get = staticmethod(query_get)
    save = staticmethod(query_save)
    delete = staticmethod(query_delete)
    referenced_by = staticmethod(query_referenced_by)


service = Service(Queries())


@router.get("")
def list_records(
    request: Request,
    offset: int = Query(0, ge=0),
    limit: int = Query(50, ge=1, le=200),
    user=Depends(require(TABLE, "view")),
):
    staff_only(user)
    data = request.app.state.store.snapshot()
    records = display_rows(data, TABLE, query_list(data))
    return {
        "items": records[offset : offset + limit],
        "total": len(records),
        "offset": offset,
        "limit": limit,
    }


@router.get("/{code}")
def get_record(code: str, request: Request, user=Depends(require(TABLE, "view"))):
    staff_only(user)
    return query_get(request.app.state.store.snapshot(), code)


@router.post("", status_code=201)
def create_record(
    body: CreateRequest, request: Request, user=Depends(require(TABLE, "create"))
):
    staff_only(user)
    with request.app.state.store.transaction() as data:
        return service.create(
            data, body.model_dump(mode="json", exclude_unset=True), user["code"]
        )


@router.patch("/{code}")
def update_record(
    code: str,
    body: UpdateRequest,
    request: Request,
    user=Depends(require(TABLE, "edit")),
):
    staff_only(user)
    with request.app.state.store.transaction() as data:
        return service.update(
            data, code, body.model_dump(mode="json", exclude_unset=True), user["code"]
        )


@router.delete("/{code}", status_code=204)
def delete_record(code: str, request: Request, user=Depends(require(TABLE, "delete"))):
    staff_only(user)
    with request.app.state.store.transaction() as data:
        service.delete(data, code, user["code"])
